const name = "Mia";
let punkte = 7;

function istBestanden(wert) {
  return wert >= 10;
}

punkte = punkte + 5;

if (istBestanden(punkte)) {
  console.log(`${name} hat bestanden.`);
} else {
  console.log(`${name} übt weiter.`);
}

const ergebnisse = [4, 10, 12, 7];
let summe = 0;
let bestanden = 0;

for (const ergebnis of ergebnisse) {
  summe += ergebnis;
  if (istBestanden(ergebnis)) bestanden += 1;
}

console.log({ summe, durchschnitt: summe / ergebnisse.length, bestanden });
